@pytest.mark.detective
def test_numbered_criteria_value_1():
    """VALUE survivor — distinguishing witness (original raises KeyError: 'inclusion')."""
    try:
        _result = numbered_criteria(study={"x": None})
    except KeyError as _exc:
        assert str(_exc) == "'inclusion'"
    except BaseException as _exc:
        pytest.fail(f"expected KeyError, got {type(_exc).__name__}: {_exc!r}")
    else:
        pytest.fail(f"expected KeyError, but the call returned {_result!r}")
